theory.intro:
Probabilities can be written as a fraction, a decimal or a percentage, and shown as a point on a number line from $0$ to $1$.

[tikz]
\begin{tikzpicture}[x=0.75cm,every node/.style={font=\small}]
\draw[thick,<->] (-0.6,0) -- (12.6,0);
\foreach \x in {0,3,6,9,12} {\draw (\x,-0.18) -- (\x,0.18);}
\node[below] at (0,-0.25) {$0$};
\node[below] at (3,-0.25) {$\displaystyle\frac{1}{4}$};
\node[below] at (6,-0.25) {$\displaystyle\frac{1}{2}$};
\node[below] at (9,-0.25) {$\displaystyle\frac{3}{4}$};
\node[below] at (12,-0.25) {$1$};
\node[above] at (0,0.25) {impossible};
\node[above] at (3,0.25) {unlikely};
\node[above] at (6,0.25) {even chance};
\node[above] at (9,0.25) {likely};
\node[above] at (12,0.25) {certain};
\draw[->] (2,1.5) -- (10,1.5);
\node[above] at (6,1.5) {more likely};
\end{tikzpicture}
[/tikz]
